CREATE OR REPLACE FUNCTION public.rol_efectivo(_usuario uuid,_rol public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
SELECT EXISTS(SELECT 1 FROM public.org_members m JOIN public.profiles p ON p.id=m.user_id AND p.activo WHERE m.org_id=public.get_user_org_id() AND m.user_id=_usuario AND (m.role=_rol OR (_rol='comite_tecnico' AND m.role='aseguramiento_calidad') OR (m.role<>'super_admin' AND EXISTS(SELECT 1 FROM public.org_suplencias s JOIN public.org_members t ON t.org_id=s.org_id AND t.user_id=coalesce(s.titular_user_id,s.rs_titular_user_id) AND t.role::text=s.rol_sustituido JOIN public.profiles tp ON tp.id=t.user_id AND tp.activo WHERE s.org_id=m.org_id AND s.suplente_user_id=m.user_id AND s.rol_sustituido IN ('admin','responsable_sanitario','aseguramiento_calidad') AND (s.rol_sustituido=_rol::text OR (_rol='comite_tecnico' AND s.rol_sustituido='aseguramiento_calidad')) AND s.estado='activa' AND s.aceptada_en IS NOT NULL AND s.revocada_en IS NULL AND s.fecha_inicio<=now() AND now()<s.fecha_fin)))) $$;
DO $k1$ DECLARE d text; BEGIN
SELECT pg_get_functiondef('public.org_suplencias_guard()'::regprocedure) INTO d;
d:=replace(d, 'NEW.rol_sustituido NOT IN (''admin'',''responsable_sanitario'')','NEW.rol_sustituido NOT IN (''admin'',''responsable_sanitario'',''aseguramiento_calidad'')');
d:=replace(d, 'IF auth.uid()<>NEW.titular_user_id AND NOT public.rol_efectivo', 'IF auth.uid()<>NEW.titular_user_id AND NOT (NEW.rol_sustituido=''aseguramiento_calidad'' AND public.rol_efectivo(auth.uid(),''responsable_sanitario'')) AND NOT public.rol_efectivo');
d:=replace(d, 'AND auth.uid()<>OLD.suplente_user_id AND NOT public.rol_efectivo','AND auth.uid()<>OLD.suplente_user_id AND NOT (OLD.rol_sustituido=''aseguramiento_calidad'' AND public.rol_efectivo(auth.uid(),''responsable_sanitario'')) AND NOT public.rol_efectivo');
d:=replace(d, 'NEW.facultades:=ARRAY[''autorizar'',''anular''];','NEW.facultades:=CASE WHEN NEW.rol_sustituido=''aseguramiento_calidad'' THEN ARRAY[''validar_indicadores''] ELSE ARRAY[''autorizar'',''anular''] END;');
EXECUTE d;
END $k1$;
CREATE OR REPLACE FUNCTION public.suplencias_traslape(_rol public.app_role,_inicio timestamptz,_fin timestamptz) RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
SELECT count(*)::integer FROM public.org_suplencias s WHERE s.org_id=public.get_user_org_id() AND s.rol_sustituido=_rol::text AND s.estado='activa' AND s.revocada_en IS NULL AND s.terminada_en IS NULL AND s.fecha_inicio<_fin AND _inicio<s.fecha_fin AND (public.rol_efectivo(auth.uid(),'admin') OR public.rol_efectivo(auth.uid(),'responsable_sanitario') OR (_rol='aseguramiento_calidad' AND public.rol_efectivo(auth.uid(),'aseguramiento_calidad'))) $$;